/**
 * Keeps a rolling log of the damage the local player takes and saves it when
 * they die, so the death can be looked at afterwards.
 *
 * Everything here is passive: it only reads what the game already shows the
 * player, shows nothing during combat and never touches input or menus.
 */
@Slf4j
@PluginDescriptor(
	name = "Death Replay",
	description = "Breaks down the damage you took in the seconds before each death",
	tags = {"death", "damage", "recap", "log", "pvm", "replay"},
	internalName = "death-replay"
)
public class DeathReplayPlugin extends Plugin
{
	/**
	 * Ticks recorded after the death tick, so the final hitsplats and the
	 * death animation are included.
	 */
	private static final int TICKS_AFTER_DEATH = 4;
	/**
	 * How long an eat/drink click waits for the inventory to change.
	 */
	private static final int CONSUME_TIMEOUT_TICKS = 3;
	private static final DateTimeFormatter ID_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss-SSS");

	@Inject
	private Client client;

	@Inject
	private DeathReplayConfig config;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private DrawManager drawManager;

	@Inject
	private Gson gson;

	private final CombatLog combatLog = new CombatLog();
	private final List<PendingConsume> pendingConsumes = new ArrayList<>();
	private TickRecord current = new TickRecord();

	/**
	 * The plugin's own thread for video compression and disk IO, kept off the
	 * shared executor because compressing frames is continuous work.
	 */
	private ExecutorService executor;
	private FrameRecorder recorder;
	private DeathStore store;
	private DeathReplayPanel panel;
	private NavigationButton navButton;
	// Swing thread only
	private ReplayViewer viewer;

	/**
	 * Game tick the player died on, or -1 when no death is being recorded.
	 */
	private int deathTick = -1;
	private DeathRecord pendingDeath;

	@AllArgsConstructor
	private static class PendingConsume
	{
		final int itemId;
		final String name;
		final int countBefore;
		final int tick;
	}

	@Override
	protected void startUp()
	{
		executor = Executors.newSingleThreadExecutor(r ->
		{
			Thread thread = new Thread(r, "death-replay");
			thread.setDaemon(true);
			return thread;
		});
		recorder = new FrameRecorder(client, drawManager, config, executor);
		recorder.start();

		panel = new DeathReplayPanel(this::deleteDeath, this::openReplay);
		BufferedImage icon = DeathReplayPanel.createIcon();
		navButton = NavigationButton.builder()
			.tooltip("Death Replay")
			.icon(icon)
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		executor.execute(() ->
		{
			try
			{
				store = new DeathStore(getPluginDirectory(), gson.newBuilder().setPrettyPrinting().create());
				List<DeathRecord> deaths = store.loadAll();
				SwingUtilities.invokeLater(() -> panel.setDeaths(deaths));
			}
			catch (IOException e)
			{
				log.warn("Unable to open the Death Replay data folder", e);
			}
		});
	}

	@Override
	protected void shutDown()
	{
		recorder.stop();
		recorder = null;
		executor.shutdownNow();
		executor = null;

		clientToolbar.removeNavigation(navButton);
		navButton = null;
		panel = null;
		store = null;
		resetRecording();

		SwingUtilities.invokeLater(() ->
		{
			if (viewer != null)
			{
				viewer.dispose();
				viewer = null;
			}
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			if (pendingDeath != null)
			{
				finishDeath();
			}
			resetRecording();
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (event.getActor() != client.getLocalPlayer())
		{
			return;
		}

		current.getHits().add(new HitRecord(
			event.getHitsplat().getAmount(),
			HitKind.fromHitsplatType(event.getHitsplat().getHitsplatType())));
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		String option = Text.removeTags(event.getMenuOption());
		if (!"Eat".equalsIgnoreCase(option) && !"Drink".equalsIgnoreCase(option))
		{
			return;
		}

		int itemId = event.getItemId();
		if (itemId <= 0)
		{
			return;
		}

		String name = Names.stripDose(client.getItemDefinition(itemId).getName());
		pendingConsumes.add(new PendingConsume(itemId, name, inventoryCount(itemId), client.getTickCount()));
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.INV || pendingConsumes.isEmpty())
		{
			return;
		}

		// Only count an eat/drink click once the item actually leaves the inventory,
		// since clicks during the eat delay do nothing.
		Iterator<PendingConsume> it = pendingConsumes.iterator();
		while (it.hasNext())
		{
			PendingConsume consume = it.next();
			if (count(event.getItemContainer(), consume.itemId) < consume.countBefore)
			{
				current.getConsumed().add(consume.name);
				it.remove();
			}
		}
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		Player local = client.getLocalPlayer();
		if (event.getActor() != local || pendingDeath != null)
		{
			return;
		}

		deathTick = client.getTickCount();

		DeathRecord record = new DeathRecord();
		LocalDateTime now = LocalDateTime.now();
		record.setId(now.format(ID_FORMAT));
		record.setTimeMillis(System.currentTimeMillis());
		record.setWorld(client.getWorld());
		record.setDeathTick(deathTick);
		record.setGear(equippedGear());

		WorldPoint location = WorldPoint.fromLocalInstance(client, local.getLocalLocation());
		if (location != null)
		{
			record.setX(location.getX());
			record.setY(location.getY());
			record.setPlane(location.getPlane());
			record.setRegionId(location.getRegionID());
		}

		pendingDeath = record;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		int tick = client.getTickCount();
		current.setTick(tick);
		current.setTimeMillis(System.currentTimeMillis());
		current.setHp(client.getBoostedSkillLevel(Skill.HITPOINTS));
		current.setMaxHp(client.getRealSkillLevel(Skill.HITPOINTS));
		current.setPrayer(client.getBoostedSkillLevel(Skill.PRAYER));
		current.setMaxPrayer(client.getRealSkillLevel(Skill.PRAYER));
		current.setSpecialAttack(client.getVarpValue(VarPlayerID.SA_ENERGY) / 10);
		current.setTarget(describe(local.getInteracting()));
		current.setPrayers(activePrayers());

		combatLog.add(current, windowTicks() + TICKS_AFTER_DEATH);
		current = new TickRecord();

		pendingConsumes.removeIf(c -> tick - c.tick > CONSUME_TIMEOUT_TICKS);

		if (pendingDeath != null && tick >= deathTick + TICKS_AFTER_DEATH)
		{
			finishDeath();
		}
	}

	@Provides
	DeathReplayConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DeathReplayConfig.class);
	}

	private void finishDeath()
	{
		DeathRecord record = pendingDeath;
		pendingDeath = null;

		List<TickRecord> ticks = combatLog.snapshot();
		record.setTicks(ticks);
		record.setLastTarget(lastTarget(ticks));
		record.setSummary(DeathSummary.compute(ticks, record.getDeathTick()));
		deathTick = -1;

		if (config.chatRecap())
		{
			String message = new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT)
				.append("Death Replay: ")
				.append(ChatColorType.NORMAL)
				.append(record.getSummary().headline() + ". Open the Death Replay panel to watch it back.")
				.build();
			chatMessageManager.queue(QueuedMessage.builder()
				.type(ChatMessageType.CONSOLE)
				.runeLiteFormattedMessage(message)
				.build());
		}

		// video from one tick before the first saved tick
		long videoFrom = ticks.isEmpty()
			? record.getTimeMillis() - config.windowSeconds() * 1000L
			: ticks.get(0).getTimeMillis() - 600;
		boolean video = config.recordVideo();
		int keep = config.maxSaved();
		int keepVideos = config.videosToKeep();
		executor.execute(() -> saveDeath(record, video ? videoFrom : -1, keep, keepVideos));
	}

	/**
	 * Runs on the plugin executor, after any frames still being compressed.
	 *
	 * @param videoFrom earliest frame time to save, or -1 for no video
	 */
	private void saveDeath(DeathRecord record, long videoFrom, int keep, int keepVideos)
	{
		DeathStore store = this.store;
		DeathReplayPanel panel = this.panel;
		FrameRecorder recorder = this.recorder;
		if (store == null)
		{
			return;
		}

		if (videoFrom >= 0 && recorder != null && keepVideos > 0)
		{
			List<CapturedFrame> frames = recorder.framesSince(videoFrom);
			if (!frames.isEmpty())
			{
				try
				{
					record.setClip(store.writeClip(record.getId(), frames));
				}
				catch (IOException e)
				{
					log.warn("Unable to save video for death {}", record.getId(), e);
				}
			}
		}

		try
		{
			store.save(record);
			store.pruneClips(keepVideos);
			List<String> pruned = store.prune(keep);
			if (panel != null)
			{
				SwingUtilities.invokeLater(() ->
				{
					panel.addDeath(record);
					pruned.forEach(panel::removeDeath);
				});
			}
		}
		catch (IOException e)
		{
			log.warn("Unable to save death {}", record.getId(), e);
		}
	}

	private void openReplay(DeathRecord record)
	{
		executor.execute(() ->
		{
			DeathStore store = this.store;
			if (store == null)
			{
				return;
			}

			ClipInfo clip = record.getClip();
			List<byte[]> frames = null;
			String message;
			if (clip == null)
			{
				message = "No video was recorded for this death";
			}
			else
			{
				message = "This video was deleted to save space (see \"Videos to keep\")";
				try
				{
					frames = store.readClip(clip);
				}
				catch (IOException e)
				{
					log.warn("Unable to read video for death {}", record.getId(), e);
					message = "Unable to read this video";
				}
			}

			List<byte[]> loaded = frames;
			String noVideo = message;
			Consumer<Component> saveVideo = loaded != null ? parent -> saveVideo(parent, record) : null;
			SwingUtilities.invokeLater(() ->
			{
				if (viewer != null)
				{
					viewer.dispose();
				}
				viewer = new ReplayViewer(record, loaded, noVideo, saveVideo);
				viewer.setVisible(true);
			});
		});
	}

	/**
	 * Asks where to save a copy of a death's video, then copies it off the
	 * client thread. Runs on the EDT.
	 */
	private void saveVideo(Component parent, DeathRecord record)
	{
		ClipInfo clip = record.getClip();
		List<Filepath> chosen = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save death video")
			.addExtensionFilter("AVI video", "avi")
			.setDefaultExtension("avi")
			.setFileName(clip.getFile())
			.showDialog(parent);
		if (chosen == null || chosen.isEmpty())
		{
			return;
		}

		Filepath target = chosen.get(0);
		if (target.exists() && JOptionPane.showConfirmDialog(parent, target.getFileName() + " already exists. Replace it?",
			"Save death video", JOptionPane.YES_NO_OPTION) != JOptionPane.YES_OPTION)
		{
			return;
		}

		executor.execute(() ->
		{
			DeathStore store = this.store;
			if (store == null)
			{
				return;
			}

			try
			{
				store.exportClip(clip, target);
			}
			catch (IOException e)
			{
				log.warn("Unable to save video for death {}", record.getId(), e);
				SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(parent, "Unable to save the video: " + e.getMessage(),
					"Save death video", JOptionPane.ERROR_MESSAGE));
			}
		});
	}

	private void deleteDeath(DeathRecord record)
	{
		executor.execute(() ->
		{
			DeathStore store = this.store;
			if (store == null)
			{
				return;
			}

			try
			{
				store.delete(record.getId());
			}
			catch (IOException e)
			{
				log.warn("Unable to delete death {}", record.getId(), e);
			}
		});
	}

	private void resetRecording()
	{
		if (recorder != null)
		{
			recorder.clear();
		}
		combatLog.clear();
		pendingConsumes.clear();
		current = new TickRecord();
		pendingDeath = null;
		deathTick = -1;
	}

	private int windowTicks()
	{
		// round up so the full number of seconds is always covered
		return (config.windowSeconds() * 10 + 5) / 6;
	}

	private List<String> activePrayers()
	{
		List<String> prayers = new ArrayList<>();
		boolean inLms = client.getVarbitValue(VarbitID.BR_INGAME) != 0;
		boolean deadeye = !inLms && client.getVarbitValue(VarbitID.PRAYER_DEADEYE_UNLOCKED) != 0;
		boolean vigour = !inLms && client.getVarbitValue(VarbitID.PRAYER_MYSTIC_VIGOUR_UNLOCKED) != 0;
		boolean zeal = inLms || client.getVarbitValue(VarbitID.PRAYER_ZEAL_UNLOCKED) != 0;

		for (Prayer prayer : Prayer.values())
		{
			if (client.getVarbitValue(prayer.getVarbit()) == 0)
			{
				continue;
			}

			// Upgraded prayers share a slot with the one they replace, matching
			// the core Prayer plugin's handling
			switch (prayer)
			{
				case EAGLE_EYE:
					if (deadeye)
					{
						continue;
					}
					break;
				case DEADEYE:
					if (!deadeye)
					{
						continue;
					}
					break;
				case MYSTIC_MIGHT:
					if (vigour)
					{
						continue;
					}
					break;
				case MYSTIC_VIGOUR:
					if (!vigour)
					{
						continue;
					}
					break;
				case PIETY:
					if (zeal)
					{
						continue;
					}
					break;
				case ZEAL:
					if (!zeal)
					{
						continue;
					}
					break;
				default:
					break;
			}

			prayers.add(Names.prayer(prayer));
		}
		return prayers;
	}

	private List<GearItem> equippedGear()
	{
		List<GearItem> gear = new ArrayList<>();
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			return gear;
		}

		for (EquipmentInventorySlot slot : EquipmentInventorySlot.values())
		{
			Item item = worn.getItem(slot.getSlotIdx());
			if (item != null && item.getId() > 0)
			{
				String name = client.getItemDefinition(item.getId()).getName();
				gear.add(new GearItem(Names.titleCase(slot.name()), item.getId(), name));
			}
		}
		return gear;
	}

	private int inventoryCount(int itemId)
	{
		return count(client.getItemContainer(InventoryID.INV), itemId);
	}

	private static int count(ItemContainer container, int itemId)
	{
		if (container == null)
		{
			return 0;
		}

		int total = 0;
		for (Item item : container.getItems())
		{
			if (item.getId() == itemId)
			{
				total += item.getQuantity();
			}
		}
		return total;
	}

	/**
	 * Describes the player's own target. This is the actor the player chose to
	 * interact with, not anything about who is attacking them.
	 */
	private static String describe(Actor actor)
	{
		if (actor == null || actor.getName() == null)
		{
			return null;
		}

		String name = Text.removeTags(actor.getName());
		int level = actor.getCombatLevel();
		if (actor instanceof NPC && level > 0)
		{
			return name + " (level " + level + ")";
		}
		return name;
	}

	private static String lastTarget(List<TickRecord> ticks)
	{
		for (int i = ticks.size() - 1; i >= 0; i--)
		{
			String target = ticks.get(i).getTarget();
			if (target != null)
			{
				return target;
			}
		}
		return null;
	}
}

package com.deathreplay;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.io.BufferedOutputStream;
import java.io.IOException;
import java.io.OutputStream;
import java.io.Reader;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.util.Filepath;

/**
 * Reads and writes death records. Does disk IO, so never call it from the
 * client thread.
 */
@Slf4j
class DeathStore
{
	private static final String EXTENSION = ".json";
	private static final String CLIP_EXTENSION = ".avi";

	private final Filepath dir;
	private final Gson gson;

	DeathStore(Filepath pluginDirectory, Gson gson) throws IOException
	{
		this.dir = pluginDirectory.joinSegment("deaths");
		this.dir.createDirectories();
		this.gson = gson;
	}

	/**
	 * @return saved deaths, newest first
	 */
	List<DeathRecord> loadAll()
	{
		List<DeathRecord> records = new ArrayList<>();
		for (Filepath file : files())
		{
			try (Reader reader = file.openBufferedReader())
			{
				DeathRecord record = gson.fromJson(reader, DeathRecord.class);
				if (record != null && record.getId() != null)
				{
					records.add(record);
				}
			}
			catch (IOException | JsonParseException e)
			{
				log.debug("Skipping unreadable death file {}", file.getFileName(), e);
			}
		}
		records.sort(Comparator.comparingLong(DeathRecord::getTimeMillis).reversed());
		return records;
	}

	void save(DeathRecord record) throws IOException
	{
		dir.joinSegment(record.getId() + EXTENSION).write(gson.toJson(record));
	}

	ClipInfo writeClip(String id, List<CapturedFrame> frames) throws IOException
	{
		String fileName = id + CLIP_EXTENSION;
		List<Long> offsets;
		try (OutputStream out = new BufferedOutputStream(dir.joinSegment(fileName).openOutputStream(), 1 << 16))
		{
			offsets = ClipWriter.write(out, frames);
		}

		ClipInfo clip = new ClipInfo();
		clip.setFile(fileName);
		clip.setWidth(frames.get(0).getWidth());
		clip.setHeight(frames.get(0).getHeight());
		for (int i = 0; i < frames.size(); i++)
		{
			CapturedFrame frame = frames.get(i);
			clip.getFrames().add(new ClipFrame(frame.getTimeMillis(), frame.getTick(), offsets.get(i), frame.getJpeg().length));
		}
		return clip;
	}

	/**
	 * @return each frame's JPEG bytes, or null if the clip file is gone
	 */
	List<byte[]> readClip(ClipInfo clip) throws IOException
	{
		Filepath file = dir.joinSegment(clip.getFile());
		if (!file.exists())
		{
			return null;
		}

		List<byte[]> frames = new ArrayList<>(clip.getFrames().size());
		try (FileChannel channel = file.openFileChannel(StandardOpenOption.READ))
		{
			for (ClipFrame frame : clip.getFrames())
			{
				ByteBuffer buffer = ByteBuffer.allocate(frame.getLength());
				long position = frame.getOffset();
				while (buffer.hasRemaining())
				{
					int read = channel.read(buffer, position + buffer.position());
					if (read < 0)
					{
						throw new IOException("clip file is truncated");
					}
				}
				frames.add(buffer.array());
			}
		}
		return frames;
	}

	boolean clipExists(ClipInfo clip)
	{
		return clip != null && dir.joinSegment(clip.getFile()).exists();
	}

	void delete(String id) throws IOException
	{
		dir.joinSegment(id + EXTENSION).deleteIfExists();
		dir.joinSegment(id + CLIP_EXTENSION).deleteIfExists();
	}

	/**
	 * Deletes the oldest deaths so at most {@code keep} remain.
	 *
	 * @return ids of the deleted deaths
	 */
	List<String> prune(int keep) throws IOException
	{
		List<String> deleted = new ArrayList<>();
		for (String id : oldestFirstBeyond(files(EXTENSION), EXTENSION, keep))
		{
			delete(id);
			deleted.add(id);
		}
		return deleted;
	}

	/**
	 * Deletes the oldest videos so at most {@code keep} remain. The deaths'
	 * data is kept.
	 */
	void pruneClips(int keep) throws IOException
	{
		for (String id : oldestFirstBeyond(files(CLIP_EXTENSION), CLIP_EXTENSION, keep))
		{
			dir.joinSegment(id + CLIP_EXTENSION).deleteIfExists();
		}
	}

	/**
	 * Copies a death's video to a file the user picked.
	 */
	void exportClip(ClipInfo clip, Filepath target) throws IOException
	{
		dir.joinSegment(clip.getFile()).copyTo(target, StandardCopyOption.REPLACE_EXISTING);
	}

	private static List<String> oldestFirstBeyond(List<Filepath> files, String extension, int keep)
	{
		// ids are timestamps, so name order is time order
		files.sort(Comparator.comparing(Filepath::getFileName).reversed());
		List<String> ids = new ArrayList<>();
		for (int i = Math.max(0, keep); i < files.size(); i++)
		{
			String name = files.get(i).getFileName();
			ids.add(name.substring(0, name.length() - extension.length()));
		}
		return ids;
	}

	private List<Filepath> files()
	{
		return files(EXTENSION);
	}

	private List<Filepath> files(String extension)
	{
		try (Stream<Filepath> stream = dir.walk(1))
		{
			return stream
				.filter(f -> f.isFile() && f.getFileName().endsWith(extension))
				.collect(Collectors.toCollection(ArrayList::new));
		}
		catch (IOException e)
		{
			log.warn("Unable to list saved deaths", e);
			return new ArrayList<>();
		}
	}
}

package com.deathreplay;

import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import lombok.Data;

/**
 * Totals worked out from a death's ticks. Purely descriptive: it reports what
 * happened and never suggests what the player should have done.
 */
@Data
public class DeathSummary
{
	/**
	 * Ticks counted as "the last few seconds" (5 ticks = 3 seconds).
	 */
	static final int BURST_TICKS = 5;

	private int windowTicks;
	private int totalDamage;
	private int burstDamage;
	private int biggestHit;
	private int hitsTaken;
	private int zeroHits;
	private int healed;
	private int itemsConsumed;
	private int startHp;
	private int maxHp;
	/**
	 * Ticks between the last time HP was above half and the death, or -1 if it
	 * never was during the window.
	 */
	private int ticksFromHalfHp = -1;
	private Map<HitKind, Integer> damageByKind = new LinkedHashMap<>();

	static DeathSummary compute(List<TickRecord> ticks, int deathTick)
	{
		DeathSummary summary = new DeathSummary();
		summary.windowTicks = ticks.size();
		if (ticks.isEmpty())
		{
			return summary;
		}

		TickRecord first = ticks.get(0);
		summary.startHp = first.getHp();
		summary.maxHp = first.getMaxHp();

		Integer lastAboveHalf = null;
		for (TickRecord tick : ticks)
		{
			if (tick.getTick() <= deathTick && tick.getMaxHp() > 0 && tick.getHp() * 2 > tick.getMaxHp())
			{
				lastAboveHalf = tick.getTick();
			}

			summary.itemsConsumed += tick.getConsumed().size();

			for (HitRecord hit : tick.getHits())
			{
				if (hit.getKind() == HitKind.HEAL)
				{
					summary.healed += hit.getAmount();
					continue;
				}

				if (hit.getKind() == HitKind.BLOCK || (hit.isDamage() && hit.getAmount() == 0))
				{
					summary.hitsTaken++;
					summary.zeroHits++;
					continue;
				}

				if (!hit.isDamage())
				{
					continue;
				}

				summary.hitsTaken++;
				summary.totalDamage += hit.getAmount();
				summary.biggestHit = Math.max(summary.biggestHit, hit.getAmount());
				summary.damageByKind.merge(hit.getKind(), hit.getAmount(), Integer::sum);
				if (tick.getTick() > deathTick - BURST_TICKS)
				{
					summary.burstDamage += hit.getAmount();
				}
			}
		}

		if (lastAboveHalf != null)
		{
			summary.ticksFromHalfHp = deathTick - lastAboveHalf;
		}

		return summary;
	}

	/**
	 * One-line recap used in chat and on the death list.
	 */
	String headline()
	{
		if (totalDamage == 0)
		{
			return "No damage recorded before this death";
		}

		return String.format("Took %d damage in the last %s (biggest hit %d)",
			burstDamage, Names.seconds(BURST_TICKS), biggestHit);
	}
}

package com.deathreplay;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.atomic.AtomicInteger;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.DrawManager;

/**
 * Keeps the last few seconds of game frames in memory as JPEGs.
 *
 * Frames are copied on the client thread (a single unscaled draw), then
 * scaled and compressed on the plugin's own executor. The buffer is only
 * touched on that executor, so saving a clip queued behind pending frames
 * always sees them.
 */
@Slf4j
class FrameRecorder implements Runnable
{
	/**
	 * Frames waiting to be compressed. Past this, new frames are skipped
	 * rather than letting a slow PC fall further behind.
	 */
	private static final int MAX_PENDING = 4;
	private static final long MAX_BUFFER_BYTES = 256L * 1024 * 1024;
	/**
	 * Longest side of a saved frame, so very large clients stay manageable.
	 */
	private static final int MAX_DIMENSION = 1920;
	/**
	 * Kept beyond the configured window so a clip always covers it.
	 */
	private static final long EXTRA_MILLIS = 5_000;

	private final Client client;
	private final DrawManager drawManager;
	private final DeathReplayConfig config;
	private final ExecutorService executor;
	private final AtomicInteger pending = new AtomicInteger();
	private long lastCaptureMillis;

	// executor thread only
	private final ArrayDeque<CapturedFrame> buffer = new ArrayDeque<>();
	private long bufferBytes;
	private JpegEncoder jpegEncoder;

	FrameRecorder(Client client, DrawManager drawManager, DeathReplayConfig config, ExecutorService executor)
	{
		this.client = client;
		this.drawManager = drawManager;
		this.config = config;
		this.executor = executor;
	}

	void start()
	{
		drawManager.registerEveryFrameListener(this);
	}

	void stop()
	{
		drawManager.unregisterEveryFrameListener(this);
		submit(() ->
		{
			clearBuffer();
			if (jpegEncoder != null)
			{
				jpegEncoder.dispose();
				jpegEncoder = null;
			}
		});
	}

	/**
	 * Called every frame on the client thread; asks for a copy of the next
	 * frame when one is due.
	 */
	@Override
	public void run()
	{
		if (!config.recordVideo() || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		long now = System.currentTimeMillis();
		if (now - lastCaptureMillis < 1000 / Math.max(1, config.videoFps()) || pending.get() >= MAX_PENDING)
		{
			return;
		}

		lastCaptureMillis = now;
		drawManager.requestNextFrameListener(this::onFrame);
	}

	/**
	 * Drops all buffered frames, e.g. after logging out.
	 */
	void clear()
	{
		submit(this::clearBuffer);
	}

	/**
	 * Must be called on the executor thread.
	 *
	 * @return buffered frames captured at or after {@code fromMillis}
	 */
	List<CapturedFrame> framesSince(long fromMillis)
	{
		List<CapturedFrame> frames = new ArrayList<>();
		for (CapturedFrame frame : buffer)
		{
			if (frame.getTimeMillis() >= fromMillis)
			{
				frames.add(frame);
			}
		}
		return frames;
	}

	private void onFrame(Image image)
	{
		int width = image.getWidth(null);
		int height = image.getHeight(null);
		if (width <= 0 || height <= 0)
		{
			return;
		}

		// The image may be a reused back buffer, so copy it before leaving the client thread
		BufferedImage copy = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = copy.createGraphics();
		g.drawImage(image, 0, 0, null);
		g.dispose();

		long time = System.currentTimeMillis();
		int tick = client.getTickCount();
		double scale = config.videoSize().getScale();

		pending.incrementAndGet();
		if (!submit(() ->
		{
			try
			{
				encode(copy, time, tick, scale);
			}
			finally
			{
				pending.decrementAndGet();
			}
		}))
		{
			pending.decrementAndGet();
		}
	}

	private void encode(BufferedImage source, long time, int tick, double scale)
	{
		scale = Math.min(scale, MAX_DIMENSION / (double) Math.max(source.getWidth(), source.getHeight()));
		// even dimensions keep video players happy
		int width = Math.max(2, (int) (source.getWidth() * scale) & ~1);
		int height = Math.max(2, (int) (source.getHeight() * scale) & ~1);

		BufferedImage scaled = source;
		if (width != source.getWidth() || height != source.getHeight())
		{
			scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
			Graphics2D g = scaled.createGraphics();
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(source, 0, 0, width, height, null);
			g.dispose();
		}

		byte[] jpeg;
		try
		{
			if (jpegEncoder == null)
			{
				jpegEncoder = new JpegEncoder();
			}
			jpeg = jpegEncoder.encode(scaled);
		}
		catch (IOException e)
		{
			log.debug("Unable to compress frame", e);
			return;
		}

		// A clip has one frame size, so start over when the client is resized
		CapturedFrame last = buffer.peekLast();
		if (last != null && (last.getWidth() != width || last.getHeight() != height))
		{
			clearBuffer();
		}

		buffer.addLast(new CapturedFrame(time, tick, width, height, jpeg));
		bufferBytes += jpeg.length;
		trim(time);
	}

	private void trim(long now)
	{
		long keepFrom = now - config.windowSeconds() * 1000L - EXTRA_MILLIS;
		Iterator<CapturedFrame> it = buffer.iterator();
		while (it.hasNext())
		{
			CapturedFrame frame = it.next();
			if (frame.getTimeMillis() >= keepFrom && bufferBytes <= MAX_BUFFER_BYTES)
			{
				break;
			}
			bufferBytes -= frame.getJpeg().length;
			it.remove();
		}
	}

	private void clearBuffer()
	{
		buffer.clear();
		bufferBytes = 0;
	}

	private boolean submit(Runnable task)
	{
		try
		{
			executor.execute(task);
			return true;
		}
		catch (RejectedExecutionException e)
		{
			// plugin is shutting down
			return false;
		}
	}
}

