package com.deathreplay;

import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageTypeSpecifier;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.metadata.IIOMetadata;
import javax.imageio.metadata.IIOMetadataNode;
import javax.imageio.stream.MemoryCacheImageOutputStream;
import org.w3c.dom.NodeList;

/**
 * Compresses frames to JPEG. Not thread safe; use one per thread.
 */
class JpegEncoder
{
	private static final float QUALITY = 0.9f;
	private static final String METADATA_FORMAT = "javax_imageio_jpeg_image_1.0";

	private final ImageWriter writer;
	private final ImageWriteParam param;

	JpegEncoder()
	{
		writer = ImageIO.getImageWritersByFormatName("jpeg").next();
		param = writer.getDefaultWriteParam();
		param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
		param.setCompressionQuality(QUALITY);
	}

	byte[] encode(BufferedImage image) throws IOException
	{
		ByteArrayOutputStream out = new ByteArrayOutputStream(128 * 1024);
		// memory-backed so ImageIO doesn't create temp files
		try (MemoryCacheImageOutputStream stream = new MemoryCacheImageOutputStream(out))
		{
			writer.setOutput(stream);
			writer.write(null, new IIOImage(image, null, fullColourMetadata(image)), param);
		}
		finally
		{
			writer.reset();
		}
		return out.toByteArray();
	}

	void dispose()
	{
		writer.dispose();
	}

	/**
	 * By default Java stores colour at half resolution (4:2:0), which smears the
	 * game's bright red and yellow text and hitsplats. This keeps full colour (4:4:4).
	 */
	private IIOMetadata fullColourMetadata(BufferedImage image) throws IOException
	{
		IIOMetadata metadata = writer.getDefaultImageMetadata(new ImageTypeSpecifier(image), param);
		IIOMetadataNode root = (IIOMetadataNode) metadata.getAsTree(METADATA_FORMAT);
		NodeList components = root.getElementsByTagName("componentSpec");
		for (int i = 0; i < components.getLength(); i++)
		{
			IIOMetadataNode component = (IIOMetadataNode) components.item(i);
			component.setAttribute("HsamplingFactor", "1");
			component.setAttribute("VsamplingFactor", "1");
		}
		metadata.setFromTree(METADATA_FORMAT, root);
		return metadata;
	}
}

package com.deathreplay;

import java.util.Locale;
import java.util.Set;
import net.runelite.api.Prayer;

final class Names
{
	private static final Set<String> SMALL_WORDS = Set.of("from", "of", "the");

	private Names()
	{
	}

	/**
	 * Turns an enum name like PROTECT_FROM_MAGIC into "Protect from Magic".
	 */
	static String prayer(Prayer prayer)
	{
		String name = prayer.name();
		if (name.startsWith("RP_"))
		{
			name = name.substring(3);
		}
		return titleCase(name);
	}

	static String titleCase(String enumName)
	{
		String[] words = enumName.toLowerCase(Locale.ROOT).split("_");
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < words.length; i++)
		{
			String word = words[i];
			if (word.isEmpty())
			{
				continue;
			}
			if (sb.length() > 0)
			{
				sb.append(' ');
			}
			if (i > 0 && SMALL_WORDS.contains(word))
			{
				sb.append(word);
			}
			else
			{
				sb.append(Character.toUpperCase(word.charAt(0))).append(word.substring(1));
			}
		}
		return sb.toString();
	}

	/**
	 * Drops the dose suffix from potion names, e.g. "Saradomin brew(3)".
	 */
	static String stripDose(String itemName)
	{
		return itemName.replaceAll("\\(\\d\\)$", "").trim();
	}

	/**
	 * Formats a tick count as seconds, e.g. 5 ticks -> "3s", 3 ticks -> "1.8s".
	 */
	static String seconds(int ticks)
	{
		int tenths = ticks * 6;
		if (tenths % 10 == 0)
		{
			return (tenths / 10) + "s";
		}
		return String.format(Locale.ROOT, "%.1fs", tenths / 10.0);
	}
}

